	/**
	 * A codec for URLs
	 * 
	 * @param <OT> the type of the object whose field is encoded/decoded.
	 */
	public static class URLDBFieldCodec<OT> : AbstractDBFieldCodec<URL, OT, StringField> where OT : DBAnnotatedObject {
		public URLDBFieldCodec(Class<OT> objectType, Field field, int column) : base(typeof(URL), objectType, typeof(StringField), field, column)
    {
		}

		protected string encode(URL url) {
			if (url == null) {
				return null;
			}
			return url.toString();
		}

		/* @Override */
		public void store(URL value, StringField f) {
			f.setString(encode(value));
		}

		/* @Override */
		protected void doStore(OT obj, DBRecord record)
    {
			record.setString(column, encode(getValue(obj)));
		}

		/* @Override */
		protected void doLoad(OT obj, DBRecord record)
    {
			try {
				string data = record.getString(column);
				if (data == null) {
					setValue(obj, null);
				}
				else {
					setValue(obj, new URI(data).toURL());
				}
			}
			catch (Exception e) when (e is MalformedURLException or URISyntaxException) {
				throw new RuntimeException(e);
			}
		}
	}

